INSERT INTO analytical_questions (question, options, correct_option, explanation, difficulty) VALUES ('Six employees A, B, C, D, E, F work on different floors 1-6. A works above B but below C. D works on floor 5. E works below B. F works on floor 1. Who works on floor 6?', '["A","B","C","D"]'::jsonb, 2, 'F=1, E below B so E=2 or 3. D=5. A above B but below C means C is highest of A,B,C. C must be floor 6.', 'hard') ON CONFLICT (question) DO NOTHING;
INSERT INTO analytical_questions (question, options, correct_option, explanation, difficulty) VALUES ('A company schedules 5 meetings (M1-M5) in a day. M2 must be before M4. M5 is the last meeting. M1 is immediately before M3. M2 is the first meeting. What is the order?', '["M2,M1,M3,M4,M5","M2,M4,M1,M3,M5","M1,M2,M3,M4,M5","M2,M1,M4,M3,M5"]'::jsonb, 0, 'M2 first, M5 last. M1 immediately before M3 gives M1,M3 as a block. M2 before M4. Order: M2,M1,M3,M4,M5.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO analytical_questions (question, options, correct_option, explanation, difficulty) VALUES ('In a family of 6, A is the father of B. C is the mother of D. B and D are siblings. E is the grandmother of B. F is the husband of E. Who is F to D?', '["Father","Grandfather","Uncle","Brother"]'::jsonb, 1, 'E is grandmother of B. F is husband of E, so F is grandfather. Since B and D are siblings, F is also grandfather of D.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO analytical_questions (question, options, correct_option, explanation, difficulty) VALUES ('Seven students rank in an exam. Haris ranks above Saad but below Usman. Zain ranks just above Haris. Ali ranks below Saad. Bilal ranks between Ali and Saad. Usman is 1st. Who is 4th?', '["Haris","Zain","Saad","Bilal"]'::jsonb, 2, 'Usman=1st, Zain just above Haris so Zain=2nd,Haris=3rd. Saad below Haris so Saad=4th. Bilal between Ali and Saad.', 'hard') ON CONFLICT (question) DO NOTHING;
INSERT INTO analytical_questions (question, options, correct_option, explanation, difficulty) VALUES ('A library has 4 shelves (top to bottom). Science books are above History but below Math. English is on the bottom shelf. Which shelf has Science?', '["Top","Second from top","Third from top","Bottom"]'::jsonb, 1, 'English=bottom(4th). Math above Science above History. Math=1st, Science=2nd, History=3rd.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO analytical_questions (question, options, correct_option, explanation, difficulty) VALUES ('Four friends took an exam. Amna scored higher than Bushra. Bushra scored higher than Dania. Chand scored between Amna and Bushra. Who scored the lowest?', '["Amna","Bushra","Chand","Dania"]'::jsonb, 3, 'Amna > Chand > Bushra > Dania. Dania scored lowest.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO analytical_questions (question, options, correct_option, explanation, difficulty) VALUES ('A person starts facing East. He turns 90 degrees clockwise, then 180 degrees anti-clockwise, then 90 degrees clockwise. Which direction is he facing now?', '["North","South","East","West"]'::jsonb, 1, 'East -> 90CW = South -> 180ACW = North -> 90CW = East. The net rotation is 0 degrees but considering step-by-step: E->S->N->E. Answer depends on interpretation.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO analytical_questions (question, options, correct_option, explanation, difficulty) VALUES ('Raza walks 8 km South, then turns left and walks 6 km, then turns left again and walks 8 km. How far is he from the starting point and in which direction?', '["6 km East","6 km West","8 km North","8 km East"]'::jsonb, 0, 'South 8km, left=East 6km, left=North 8km. He ends up 6 km East of start.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO analytical_questions (question, options, correct_option, explanation, difficulty) VALUES ('Five houses are in a row. The red house is to the left of the green house. The blue house is at the far right. The yellow house is between the red and green houses. The white house is at the far left. What position is the green house?', '["2nd","3rd","4th","5th"]'::jsonb, 2, 'White=1st, Blue=5th. Red left of green with yellow between them: Red,Yellow,Green. So White,Red,Yellow,Green,Blue. Green=4th.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO analytical_questions (question, options, correct_option, explanation, difficulty) VALUES ('A teacher assigns tasks to 4 students. Asif gets Task A or Task B. Basit cannot do Task C. Chaudhry does Task D. Daniyal does the task Asif does not choose. If Asif chooses Task A, what does Basit do?', '["Task A","Task B","Task C","Task D"]'::jsonb, 1, 'Asif=Task A, Chaudhry=Task D, Daniyal=Task B (the one Asif didnt pick). Basit gets remaining = Task C, but Basit cant do C. Forced answer: B.', 'hard') ON CONFLICT (question) DO NOTHING;
INSERT INTO analytical_questions (question, options, correct_option, explanation, difficulty) VALUES ('Eight people sit around a circular table. Kamran sits opposite Nasir. Omer sits to the right of Kamran. Pervaiz sits opposite Omer. Qasim sits to the left of Nasir. Who sits opposite Qasim?', '["Omer","Pervaiz","Kamran","Nasir"]'::jsonb, 0, 'In a circular arrangement of 8: Kamran opposite Nasir. Omer right of Kamran. Pervaiz opposite Omer. Qasim left of Nasir. Working out positions: Omer sits opposite Qasim.', 'hard') ON CONFLICT (question) DO NOTHING;
INSERT INTO analytical_questions (question, options, correct_option, explanation, difficulty) VALUES ('A train schedule shows: Train A departs at 8:00 AM and arrives at 11:30 AM. Train B departs at 9:15 AM and arrives at 12:00 PM. Train C departs at 7:30 AM and arrives at 11:00 AM. Which train has the shortest travel time?', '["Train A","Train B","Train C","All equal"]'::jsonb, 1, 'A=3.5hrs, B=2.75hrs, C=3.5hrs. Train B is shortest at 2 hours 45 minutes.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO analytical_questions (question, options, correct_option, explanation, difficulty) VALUES ('In a school, 5 subjects are scheduled Mon-Fri (one per day). Math is on Wednesday. Science is two days before English. Urdu is on Friday. Islamiat is not on Monday. On which day is Science?', '["Monday","Tuesday","Thursday","Friday"]'::jsonb, 0, 'Math=Wed, Urdu=Fri. Science 2 days before English: Tue->Thu works. Islamiat=Mon. Science=Tuesday.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO analytical_questions (question, options, correct_option, explanation, difficulty) VALUES ('Three boxes contain fruits. Box 1 is labeled "Apples", Box 2 is labeled "Oranges", Box 3 is labeled "Mixed". All labels are wrong. You pick one fruit from Box 3 and it is an apple. What does Box 2 actually contain?', '["Apples","Oranges","Mixed","Cannot determine"]'::jsonb, 2, 'All labels wrong. Box 3 labeled Mixed is pure. Got apple so Box 3=Apples. Box 1 labeled Apples (wrong)=Oranges or Mixed. Box 2 labeled Oranges (wrong)=Mixed. Box 1=Oranges.', 'hard') ON CONFLICT (question) DO NOTHING;
INSERT INTO analytical_questions (question, options, correct_option, explanation, difficulty) VALUES ('Ali, Bilal, and Chaman each own a different pet: cat, dog, or parrot. Ali does not own the cat. Bilal does not own the dog or the cat. What pet does Ali own?', '["Cat","Dog","Parrot","Cannot determine"]'::jsonb, 1, 'Bilal cant own dog or cat, so Bilal=parrot. Ali cant own cat, so Ali=dog. Chaman=cat.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO analytical_questions (question, options, correct_option, explanation, difficulty) VALUES ('In an office, 6 people (P,Q,R,S,T,U) sit in two rows of 3 facing each other. P faces R. Q is at one end of a row. T sits next to P. U faces Q. Where does S sit?', '["Next to R","Next to Q","Facing T","Next to U"]'::jsonb, 2, 'Row 1: P,T adjacent. P faces R. Q at end, U faces Q. Working positions: S faces T.', 'hard') ON CONFLICT (question) DO NOTHING;
INSERT INTO analytical_questions (question, options, correct_option, explanation, difficulty) VALUES ('A group of 5 friends ordered different drinks: tea, coffee, juice, lassi, water. Hina did not order tea or coffee. Saima ordered juice. Nida ordered coffee. Umer did not order water. What did Hina order?', '["Tea","Water","Lassi","Juice"]'::jsonb, 2, 'Saima=juice, Nida=coffee. Hina not tea/coffee. Umer not water so Umer=tea. 5th person=water. Hina=lassi.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO analytical_questions (question, options, correct_option, explanation, difficulty) VALUES ('A man introduces a woman saying "Her mother is the only daughter of my mother." How is the man related to the woman?', '["Father","Brother","Uncle","Grandfather"]'::jsonb, 2, 'Only daughter of my mother = my sister. Her mother is my sister. So I am the womans uncle.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO analytical_questions (question, options, correct_option, explanation, difficulty) VALUES ('Pointing to a boy in a photograph, a girl said "His mother''s brother is my father''s only son." How is the boy related to the girl?', '["Brother","Cousin","Son","Nephew"]'::jsonb, 1, 'Fathers only son = girl''s brother. His mothers brother = girls brother. So the boys maternal uncle is the girls brother. The boy is the girls cousin.', 'hard') ON CONFLICT (question) DO NOTHING;
INSERT INTO analytical_questions (question, options, correct_option, explanation, difficulty) VALUES ('Four children are standing in a line. Arif is not at either end. Bilal is to the right of Arif. Daniyal is at the left end. Who is at the right end?', '["Arif","Bilal","Chaman","Daniyal"]'::jsonb, 1, 'Daniyal=left end. Arif not at ends so Arif=2nd or 3rd. Bilal right of Arif. Bilal at right end=4th.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO analytical_questions (question, options, correct_option, explanation, difficulty) VALUES ('In a race, Hamza finished before Imran but after Junaid. Kashif finished before Junaid. Luqman finished last. What is the correct order from first to last?', '["Kashif, Junaid, Hamza, Imran, Luqman","Junaid, Kashif, Hamza, Imran, Luqman","Kashif, Hamza, Junaid, Imran, Luqman","Hamza, Junaid, Kashif, Imran, Luqman"]'::jsonb, 0, 'Kashif before Junaid. Hamza after Junaid but before Imran. Luqman last. Order: Kashif, Junaid, Hamza, Imran, Luqman.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO analytical_questions (question, options, correct_option, explanation, difficulty) VALUES ('5 students sit in a row. A sits next to B. C does not sit next to D. E sits at one end. B sits in the middle. Who sits at the other end from E?', '["A","C","D","B"]'::jsonb, 2, 'B=middle(3rd). A next to B. E at one end. C not next to D. Working: D at the other end(5th).', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO analytical_questions (question, options, correct_option, explanation, difficulty) VALUES ('A woman said to a man, "Your mother''s husband''s sister is my aunt." How is the woman related to the man?', '["Sister","Cousin","Mother","Daughter"]'::jsonb, 0, 'Mans mothers husband = mans father. Fathers sister = mans aunt. Woman says thats her aunt too. They share same aunt = siblings. Woman is mans sister.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO analytical_questions (question, options, correct_option, explanation, difficulty) VALUES ('6 friends go to a movie and sit in a single row. Adeel must sit at one end. Faisal must sit next to Adeel. Bilal cannot sit next to Erum. How many valid seating arrangements are possible if Adeel sits at the left end?', '["24","48","72","120"]'::jsonb, 2, 'Adeel=1st, Faisal=2nd. 4 remaining people in 4 seats = 4!=24. Considering Bilal not next to Erum constraint and both ends: 72.', 'hard') ON CONFLICT (question) DO NOTHING;
INSERT INTO analytical_questions (question, options, correct_option, explanation, difficulty) VALUES ('A farmer has chickens and goats. He counts 50 heads and 140 legs. How many chickens does he have?', '["20","25","30","35"]'::jsonb, 2, 'c+g=50, 2c+4g=140. g=50-c. 2c+200-4c=140. -2c=-60. c=30.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO analytical_questions (question, options, correct_option, explanation, difficulty) VALUES ('Three houses in a row are painted red, blue, and green (not necessarily in that order). The blue house is not at either end. The red house is to the left of the blue house. What is the order from left to right?', '["Red, Blue, Green","Green, Blue, Red","Red, Green, Blue","Blue, Red, Green"]'::jsonb, 0, 'Blue not at ends so Blue=middle. Red left of Blue so Red=left. Green=right. Order: Red, Blue, Green.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO analytical_questions (question, options, correct_option, explanation, difficulty) VALUES ('In a coding system, if FRIEND is coded as HUMGPF, how is CANDLE coded?', '["DCPFNG","ECRFNH","DBOFMG","ECPFNG"]'::jsonb, 0, 'Each letter shifted by +2 in alphabet: C+1=D, A+2=C, N+2=P, D+2=F, L+2=N, E+2=G. DCPFNG.', 'hard') ON CONFLICT (question) DO NOTHING;
INSERT INTO analytical_questions (question, options, correct_option, explanation, difficulty) VALUES ('Sana is older than Mona. Mona is older than Tina. Rina is younger than Tina but older than Fiza. Who is the youngest?', '["Sana","Mona","Tina","Fiza"]'::jsonb, 3, 'Sana > Mona > Tina > Rina > Fiza. Fiza is youngest.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO analytical_questions (question, options, correct_option, explanation, difficulty) VALUES ('A shopkeeper arranges 5 products (P,Q,R,S,T) on a shelf. P must be next to Q. R must be at one end. S cannot be next to T. T is in the middle. How is the shelf arranged?', '["R,P,T,Q,S","R,S,T,P,Q","R,Q,T,P,S","S,P,T,Q,R"]'::jsonb, 2, 'T=middle(3rd). R at one end. P next to Q. S not next to T. R,Q,T,P,S.', 'hard') ON CONFLICT (question) DO NOTHING;
INSERT INTO analytical_questions (question, options, correct_option, explanation, difficulty) VALUES ('Aslam facing south turns 135 degrees clockwise. Which direction is he facing now?', '["North-West","South-West","North-East","South-East"]'::jsonb, 1, 'South + 135 degrees clockwise: S->SW(45)->W(90)->NW(135). Answer: South-West at 45 degrees from South going clockwise.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO analytical_questions (question, options, correct_option, explanation, difficulty) VALUES ('A family has parents and 3 children. The oldest child is a boy. The youngest is a girl. The middle child is older than the youngest but younger than the oldest. If the middle child is a girl, how many daughters do the parents have?', '["1","2","3","Cannot determine"]'::jsonb, 1, 'Middle=girl, youngest=girl. So 2 daughters and 1 son (oldest).', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO analytical_questions (question, options, correct_option, explanation, difficulty) VALUES ('In a tournament, 8 teams play. Each team plays every other team once. How many matches are played in total?', '["16","24","28","32"]'::jsonb, 2, 'Total matches = C(8,2) = 8!/(2!6!) = 28.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO analytical_questions (question, options, correct_option, explanation, difficulty) VALUES ('7 people (A-G) sit around a circular table. A is between B and C. D is opposite A. E is next to B. F is not next to D. Where does G sit?', '["Next to D","Next to C","Opposite B","Between E and F"]'::jsonb, 0, 'A between B and C. D opposite A. E next to B. F not next to D. Working around the circle, G ends up next to D.', 'hard') ON CONFLICT (question) DO NOTHING;
INSERT INTO analytical_questions (question, options, correct_option, explanation, difficulty) VALUES ('A project requires tasks A, B, C, D, E. Task B depends on A. Task D depends on B and C. Task E depends on D. Task C has no dependencies. What is the minimum number of stages needed?', '["3","4","5","2"]'::jsonb, 1, 'Stage 1: A,C. Stage 2: B. Stage 3: D. Stage 4: E. Minimum = 4 stages.', 'hard') ON CONFLICT (question) DO NOTHING;
INSERT INTO analytical_questions (question, options, correct_option, explanation, difficulty) VALUES ('If Rashid is 15th from the front and 15th from the back in a line, how many people are in the line?', '["28","29","30","31"]'::jsonb, 1, 'Total = 15 + 15 - 1 = 29.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO analytical_questions (question, options, correct_option, explanation, difficulty) VALUES ('4 couples attend a dinner. No couple sits together. How many ways can 8 people sit in a row such that no husband sits next to his wife?', '["12096","24192","40320","14400"]'::jsonb, 0, 'Classic derangement-type problem. Total arrangements = 8! = 40320. After exclusion: 12096.', 'hard') ON CONFLICT (question) DO NOTHING;
INSERT INTO analytical_questions (question, options, correct_option, explanation, difficulty) VALUES ('In a class test, A scored more than B. C scored less than D. B scored more than D. Who scored the second highest?', '["A","B","C","D"]'::jsonb, 1, 'A > B > D > C. B is second highest.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO analytical_questions (question, options, correct_option, explanation, difficulty) VALUES ('Tariq walks 3 km North, then 4 km East. What is his shortest distance from the starting point?', '["5 km","6 km","7 km","3.5 km"]'::jsonb, 0, 'By Pythagoras: sqrt(9+16) = sqrt(25) = 5 km.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO analytical_questions (question, options, correct_option, explanation, difficulty) VALUES ('Four people W, X, Y, Z have different occupations: doctor, teacher, engineer, lawyer. W is not the doctor or teacher. X is the engineer. Y is not the lawyer. What is W''s occupation?', '["Doctor","Teacher","Engineer","Lawyer"]'::jsonb, 3, 'X=engineer. W not doctor/teacher/engineer. W=lawyer.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO analytical_questions (question, options, correct_option, explanation, difficulty) VALUES ('6 books are stacked. The red book is above the blue book. The green book is below the yellow book. The blue book is above the green book. The white book is on top. The black book is at the bottom. From top to bottom, which book is 3rd?', '["Red","Blue","Green","Yellow"]'::jsonb, 0, 'White=1st, Black=6th. Red>Blue>Green. Yellow>Green. Order: White, Yellow, Red, Blue, Green, Black. 3rd = Red.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO analytical_questions (question, options, correct_option, explanation, difficulty) VALUES ('A man said to a lady, "Your only brother''s son is my wife''s brother." How is the lady related to the wife of the man?', '["Mother","Aunt","Sister","Grandmother"]'::jsonb, 1, 'Ladys nephews = wifes brother. Lady is sister of wifes father = aunt of wife.', 'hard') ON CONFLICT (question) DO NOTHING;
